1	import { notFound } from "next/navigation";
2	import Link from "next/link";
3	import { db } from "@/lib/db";
4	import { requireUser } from "@/lib/auth";
5	import { PageHeader, StatusDot, Badge, timeAgo } from "@/components/ui/primitives";
6	import { ReplyForm, TicketStatusButton } from "@/components/customer/TicketForms";
7	import { markTicketMessagesRead } from "@/lib/actions-support";
8	import { MessageAttachment } from "@/components/support/MessageAttachment";
9	import { EditableMessageBody } from "@/components/support/EditableMessageBody";
10	
11	export const dynamic = "force-dynamic";
12	
13	const priorityTone: Record<string, "slate" | "brand" | "amber" | "red"> = {
14	  LOW: "slate",
15	  NORMAL: "brand",
16	  HIGH: "amber",
17	  URGENT: "red",
18	};
19	
20	export default async function TicketPage({ params }: { params: Promise<{ id: string }> }) {
21	  const { id } = await params;
22	  const user = await requireUser();
23	  const ticket = await db.ticket.findUnique({
24	    where: { id },
25	    include: {
26	      messages: {
27	        select: {
28	          id: true,
29	          body: true,
30	          isStaff: true,
31	          authorId: true,
32	          createdAt: true,
33	          editedAt: true,
34	          attachmentMime: true,
35	          attachmentName: true,
36	          attachmentSize: true,
37	          author: true,
38	        },
39	        orderBy: { createdAt: "asc" },
40	      },
41	    },
42	  });
43	  if (!ticket || (ticket.userId !== user.id && user.role !== "ADMIN")) notFound();
44	
45	  // Read receipts flow staff -> customer only ("read receipts from customers,
46	  // but they dont get them from us"): viewing the ticket as its owning customer
47	  // stamps `readAt` on every unread staff message, but this page never RENDERS
48	  // any receipt itself — that indicator only ever appears on the admin thread.
49	  // A no-op for anyone but the ticket's own customer (including an admin
50	  // viewing here as themselves, not impersonating).
51	  await markTicketMessagesRead(ticket.id);
52	
53	  return (
54	    <div className="space-y-6">
55	      <PageHeader title={ticket.subject} sub={`Opened ${timeAgo(ticket.createdAt)}`}>
56	        <Link href="/dashboard/support" className="btn-ghost">
57	          ← All tickets
58	        </Link>
59	        <TicketStatusButton ticketId={ticket.id} status={ticket.status} />
60	      </PageHeader>
61	
62	      <div className="flex items-center gap-3">
63	        <StatusDot status={ticket.status} />
64	        <Badge tone={priorityTone[ticket.priority] ?? "slate"}>{ticket.priority.toLowerCase()}</Badge>
65	      </div>
66	
67	      <div className="space-y-4">
68	        {ticket.messages.map((m) => (
69	          <div key={m.id} className={`flex ${m.isStaff ? "justify-start" : "justify-end"}`}>
70	            <div
71	              className={`max-w-[85%] rounded-2xl px-4 py-3 sm:max-w-[70%] ${
72	                m.isStaff
73	                  ? "glass rounded-tl-sm"
74	                  : "rounded-tr-sm bg-gradient-to-br from-accent-blue/30 to-brand-500/30 ring-1 ring-brand-500/30"
75	              }`}
76	            >
77	              <div className="mb-1 flex items-baseline justify-between gap-4">
78	                <span className={`text-xs font-semibold ${m.isStaff ? "text-brand-300" : "text-slate-200"}`}>
79	                  {m.isStaff ? `${m.author.name} · Nxeon staff` : m.author.name}
80	                </span>
81	                <span className="text-[11px] text-slate-500">{timeAgo(m.createdAt)}</span>
82	              </div>
83	              <EditableMessageBody
84	                messageId={m.id}
85	                initialBody={m.body}
86	                createdAtIso={m.createdAt.toISOString()}
87	                editedAtIso={m.editedAt?.toISOString() ?? null}
88	                canEditPermission={m.authorId === user.id && ticket.status !== "CLOSED"}
89	                bodyClassName="whitespace-pre-wrap text-sm text-slate-100"
90	              />
91	              {m.attachmentMime && m.attachmentName && (
92	                <MessageAttachment
93	                  messageId={m.id}
94	                  mime={m.attachmentMime}
95	                  name={m.attachmentName}
96	                  size={m.attachmentSize ?? 0}
97	                />
98	              )}
99	            </div>
100	          </div>
101	        ))}
102	      </div>
103	
104	      {ticket.status === "CLOSED" ? (
105	        <div className="card text-center text-sm text-slate-400">
106	          This ticket is closed. Reopen it above to continue the conversation.
107	        </div>
108	      ) : (
109	        <div className="card">
110	          <p className="section-label mb-3">Reply</p>
111	          <ReplyForm ticketId={ticket.id} />
112	        </div>
113	      )}
114	    </div>
115	  );
116	}
