1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { EmptyState, timeAgo } from "@/components/ui/primitives";
4	import { PortalHero } from "@/components/portal/PortalHero";
5	import { humanizeAction, actionDotColor } from "@/components/customer/humanize";
6	
7	export const dynamic = "force-dynamic";
8	
9	export default async function ActivityPage() {
10	  const user = await requireUser();
11	  const logs = await db.auditLog.findMany({
12	    where: { userId: user.id },
13	    orderBy: { createdAt: "desc" },
14	    take: 100,
15	  });
16	
17	  return (
18	    <div className="space-y-6">
19	      <PortalHero variant="activity" title="Activity" sub="Everything that happened on your account, newest first." />
20	
21	      {logs.length === 0 ? (
22	        <EmptyState
23	          title="No activity yet"
24	          sub="Actions like deployments, renewals and logins will show up here."
25	        />
26	      ) : (
27	        <div className="card">
28	          <ol className="relative ml-1.5 border-l border-white/[0.08]">
29	            {logs.map((log) => (
30	              <li key={log.id} className="relative pb-6 pl-6 last:pb-0">
31	                <span
32	                  className={`absolute -left-[5px] top-1.5 h-2.5 w-2.5 rounded-full ring-4 ring-navy-900 ${actionDotColor(log.action)}`}
33	                />
34	                <div className="flex flex-wrap items-baseline justify-between gap-2">
