36	                  <span className="text-xs text-slate-500" title={log.createdAt.toISOString()}>
37	                    {timeAgo(log.createdAt)}
38	                  </span>
39	                </div>
40	                {log.detail && (
41	                  <p className="mt-0.5 break-all font-mono text-xs text-slate-500">{log.detail}</p>
42	                )}
43	              </li>
44	            ))}
45	          </ol>
46	        </div>
47	      )}
48	    </div>
49	  );
50	}
