84	export function ReplyForm({ ticketId }: { ticketId: string }) {
85	  const [state, action, pending] = useActionState(replyTicket, {});
86	  const [body, setBody] = useState("");
87	  const composerRef = useRef<ReplyComposerHandle>(null);
88	  // A reply has two outcomes and they want OPPOSITE things from the field, which
89	  // is why simply making it controlled is not enough:
90	  //   - rejected  → keep every character; React 19 would otherwise blank up to
91	  //                 10,000 of them on the form-action submit, and the customer
92	  //                 will not retype them.
93	  //   - accepted  → clear it, or the sent reply sits there looking unsent and
94	  //                 gets sent twice.
95	  // So the field is controlled and cleared only on a submit that came back
96	  // without an error, watching the pending edge rather than the state shape
97	  // (the action returns `{}` for success, which is indistinguishable from its
98	  // initial value).
99	  const wasPending = useRef(false);
100	  useEffect(() => {
101	    if (wasPending.current && !pending && !state?.error) {
102	      setBody("");
103	      composerRef.current?.resetAttachment();
104	    }
105	    wasPending.current = pending;
106	  }, [pending, state]);
107	  return (
108	    <form action={action} className="space-y-3">
109	      <input type="hidden" name="ticketId" value={ticketId} />
110	      {state?.error && <p className="text-sm text-red-400">{state.error}</p>}
111	      <ReplyComposer
112	        ref={composerRef}
113	        value={body}
114	        onChange={setBody}
115	        placeholder="Write a reply…"
116	        disabled={pending}
117	      />
118	      <div className="flex justify-end">
119	        <button className="btn-primary px-6" disabled={pending}>
120	          {pending ? "Sending…" : "Send reply"}
121	        </button>
122	      </div>
123	    </form>
124	  );
125	}
