26	      if (res?.error) setError(res.error);
27	    });
28	  };
29	
30	  return (
31	    <div className="card border-red-500/20">
32	      <h2 className="mb-1 font-semibold">Privacy &amp; data</h2>
33	      <p className="mb-5 text-sm text-slate-400">
34	        Download everything we hold about your account, or permanently close it.
35	      </p>
36	
37	      <div className="mb-6">
38	        <p className="mb-1 text-sm font-medium">Download my data</p>
39	        <p className="mb-3 text-xs text-slate-500">
40	          A JSON file with your profile, servers, wallet history, invoices, domains, tickets, SSH
41	          keys and team memberships. Secrets and passwords are never included.
42	        </p>
43	        <a className="btn-secondary inline-flex" href="/api/account/export" download>
44	          Download my data
45	        </a>
46	      </div>
47	
48	      <hr className="my-6 border-white/[0.06]" />
49	
50	      <div>
51	        <p className="mb-1 text-sm font-medium text-red-300">Delete account</p>
