11	 * Cloudflare used to be a hidden, email-only setting. It's now a visible account
12	 * integration: connect once here (or from any DNS surface) and the same
13	 * connection powers mail records, pointing websites at a server, and the
14	 * post-migration domain cutover.
15	 */
16	export function CloudflareIntegration({
17	  connected: initialConnected,
18	  kind,
19	  oauthAvailable,
20	  scopeSummary,
21	  redirectUri,
22	}: {
23	  connected: boolean;
24	  kind: "oauth" | "token" | null;
25	  oauthAvailable: boolean;
26	  scopeSummary: string;
27	  redirectUri: string;
28	}) {
29	  const [connected, setConnected] = useState(initialConnected);
30	  const [error, setError] = useState<string | null>(null);
31	  const [status, setStatus] = useState<string | null>(null);
32	  const [pending, start] = useTransition();
33	
34	  function disconnect() {
35	    setError(null);
36	    setStatus(null);
37	    start(async () => {
38	      const res = await disconnectCloudflare();
39	      if (res?.error) setError(res.error);
40	      else {
41	        setConnected(false);
42	        setStatus("Cloudflare disconnected. We can no longer read or change your DNS.");
43	      }
44	    });
45	  }
46	
47	  return (
48	    <div className="card">
49	      <CloudflareResultBanner />
50	
51	      <div className="mb-1 flex flex-wrap items-center justify-between gap-2">
