87	          <span className="text-xs text-slate-500">
88	            {kind === "oauth"
89	              ? "Removes our access here and revokes it at Cloudflare. Records we already created stay in place."
90	              : "Deletes the stored API token. Records we already created stay in place."}
91	          </span>
92	        </div>
93	      ) : (
94	        <CloudflareConnect
95	          intent="settings"
96	          next="/dashboard/settings"
97	          connectedHint={false}
98	          onConnected={() => setConnected(true)}
99	        />
100	      )}
101	
102	      {!oauthAvailable && (
