7	
8	/**
9	 * Connect / disconnect UI for the customer's own Anthropic API key (BYOK).
10	 * NEVER displays the stored key — only whether one is connected.
11	 */
12	export function ClaudeKeyConnect({ connected }: { connected: boolean }) {
13	  const router = useRouter();
14	  const [key, setKey] = useState("");
15	  const [error, setError] = useState<string | null>(null);
16	  const [pending, startTransition] = useTransition();
17	
18	  const onConnect = (e: React.FormEvent) => {
19	    e.preventDefault();
20	    setError(null);
21	    startTransition(async () => {
22	      const res = await connectAnthropicKey(key);
23	      if (res.error) {
24	        setError(res.error);
25	        return;
26	      }
27	      setKey("");
28	      router.refresh();
29	    });
30	  };
31	
32	  const onDisconnect = () => {
33	    setError(null);
34	    startTransition(async () => {
35	      await disconnectAnthropicKey();
36	      router.refresh();
37	    });
38	  };
39	
40	  return (
41	    <div className="card space-y-4 p-5">
42	      <div className="flex flex-wrap items-center justify-between gap-3">
