45	          <p className="mt-1 max-w-xl text-sm text-slate-400">
46	            Build with AI runs on <span className="font-medium text-slate-300">your</span> Anthropic API
47	            key. It&apos;s encrypted before storage and never shown again.
48	          </p>
49	        </div>
50	        <Badge tone={connected ? "green" : "slate"}>{connected ? "Connected" : "Not connected"}</Badge>
51	      </div>
