64	          <input
65	            type="password"
66	            className="input font-mono"
67	            placeholder="sk-ant-…"
68	            value={key}
69	            onChange={(e) => setKey(e.target.value)}
70	            autoComplete="off"
71	            spellCheck={false}
72	            disabled={pending}
73	          />
74	          {error && <p className="text-sm text-red-300">{error}</p>}
75	          <button type="submit" className="btn-primary" disabled={pending || key.trim().length < 12}>
76	            {pending ? "Connecting…" : "Connect key"}
77	          </button>
